using namespace std;

int main() {
    int n;
    long long m;
    if (scanf("%d %lld", &n, &m) != 2) return 0;
    vector<long long> a(n);
    for (auto &x : a) {
        scanf("%lld", &x);
        x %= m;
    }
    // freq counts remainders strictly left of the middle index.
    vector<long long> freq(m, 0);
    long long answer = 0;
    if (n) freq[a[0]] = 1;
    for (int mid = 1; mid < n - 1; mid++) {
        long long r = a[mid];
        for (int k = mid + 1; k < n; k++) answer += freq[(2 * m - r - a[k]) % m];
        freq[r]++;
    }
    printf("%lld\n", answer);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        int m = nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = (int) (nextLong() % m);
        // freq counts remainders strictly left of the middle index.
        long[] freq = new long[m];
        long answer = 0;
        if (n > 0) freq[a[0]] = 1;
        for (int mid = 1; mid < n - 1; mid++) {
            int r = a[mid];
            for (int k = mid + 1; k < n; k++) answer += freq[(2 * m - r - a[k]) % m];
            freq[r]++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt() % m
	}
	// freq counts remainders strictly left of the middle index.
	freq := make([]int64, m)
	var answer int64
	if n > 0 {
		freq[a[0]] = 1
	}
	for mid := 1; mid < n-1; mid++ {
		r := a[mid]
		for k := mid + 1; k < n; k++ {
			answer += freq[(2*m-r-a[k])%m]
		}
		freq[r]++
	}
	fmt.Println(answer)
}
